Method.Source:
//int                     qty;
public Object dialog()
{
    Dialog                      dialog = super();
    Map                         pages = TFMPagesProvider::getAllPages().getPages();
    MapEnumerator               pagesEnum = pages.getEnumerator();
    TFMPages					mobPages;
    TFMPage						page;
    MapEnumerator               pageEnum;


    // Set a title for dialog
    dialog.caption("@TFM:GenerateFromDocuments");
    fields = new Map (Types::String, Types::Class);
    savedPages = new Map (Types::String, Types::Class);
    while (pagesEnum.moveNext())
    {
        dlg = dialog.addGroup(pagesEnum.currentKey());
        dlg.hideIfEmpty(false);
        mobPages = pagesEnum.currentValue();
        pageEnum = mobPages.getPages().GetEnumerator();
        while (pageEnum.moveNext())
        {
            page = pageEnum.currentValue();
            checkmarkField = dialog.addField(extendedTypeStr(NoYesId), pageEnum.currentKey() + ' (' + page.parmType() + ')');
            checkmarkField.value(0);
            fields.insert(pageEnum.currentKey(),checkmarkField);
            savedPages.insert(pageEnum.currentKey(),page);
        }
    }

    return dialog;
}

    public void run()
    {
        MapEnumerator mEnum = fields.getEnumerator();
        //str             output;

        while ( mEnum.moveNext())
        {
            checkmarkField = mEnum.currentValue();
            if (!checkmarkField.value())
            {
                continue;
            }
            //Info (mEnum.currentKey() +' '+  strFmt('%1',checkmarkField.value()));

            TFMDeltaPages::createFromPageClass(savedPages.lookup(mEnum.currentKey()), true);


        }
		if (ds)
        {

            ds.executeQuery();
        }
    }

