public static void main(Args _args)
{
    TFMPageClassOverrideDialog pagesDialog = new TFMPageClassOverrideDialog();
    pagesDialog.setDataSource(_args.record().datasource());

    // Prompt the dialog, if user clicks in OK it returns true
    if (pagesDialog.prompt())
    {
        pagesDialog.runOperation();
    }
}

